export function meterDeltasSorted(): (VintageMeter & { sortDelta: number })[] {
  return [...VINTAGE_METERS]
    .map((m) => ({ ...m, sortDelta: m.delta }))
    .sort((a, b) => b.sortDelta - a.sortDelta);
}

export function propertyMixSorted() {
  return [...PROPERTY_MIX].sort((a, b) => b.balanceBn - a.balanceBn);
}

export function momDeltaSorted() {
  return [...MOM_COMPARE].sort((a, b) => b.delta - a.delta);
}

export function fmtPct(n: number, digits = 2): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 2): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

export function fmtBn(n: number, digits = 2): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}$${Math.abs(n).toFixed(digits)}B`;
}

export function fmtMm(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}$${Math.abs(n).toFixed(digits)}M`;
}

export function fmtUsdBn(n: number, digits = 2): string {
  return `$${n.toFixed(digits)}B`;
}

