"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  DEBT_YIELD_BUCKETS,
  FED_SA_PATH,
  HEADLINE,
  MOM_COMPARE,
  PROPERTY_MIX,
  SOURCE_NOTE,
  SOURCES,
  STRESS_MAP,
  VINTAGE_METERS,
  YEAR_CALENDAR,
  fmtBn,
  fmtMm,
  fmtPct,
  fmtPp,
  fmtUsdBn,
  meterDeltasSorted,
  momDeltaSorted,
  propertyMixSorted,
} from "@/data/bank-commercial-credit-update-202608-data";

// viz-types: signed ?? bars, July???Aug dumbbell, property pie+bars, DY stacked area, bank??wall scatter, Fed path | layout: canvas
// viz-plan: wall meters; MoM compare; property mix; debt-yield buckets; dual ledger; carried Fed SA; panel + compare + book controls

type Panel = "meters" | "mom" | "mix" | "dyield" | "ledger" | "fed";
type MomLens = "levels" | "deltas";
type LedgerBook = "all" | "bank" | "cmbs" | "wall";

const OFFICE = "#e11d48";
const RETAIL = "#f59e0b";
const MIXED = "#8b5cf6";
const OTHER = "#94a3b8";
const COOL = "#14b8a6";
const HEAT = "#f43f5e";
const PRIOR = "#94a3b8";
const NEW = "#0f172a";
const CRE = "#0ea5e9";
const CARDS = "#f59e0b";
const CI = "#a78bfa";
const CLEAR = "#14b8a6";
const FRICTION = "#f59e0b";
const SEVERE = "#e11d48";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">{label}</span>
      {options.map((o) => {
        const on = o.id === value;
        return (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              on ? "bg-slate-900 text-white shadow-sm" : "bg-slate-100 text-slate-600 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

export function BankCommercialCreditUpdate202608Dashboard() {
  const [panel, setPanel] = useState<Panel>("meters");
  const [momLens, setMomLens] = useState<MomLens>("levels");
  const [ledgerBook, setLedgerBook] = useState<LedgerBook>("all");

  const meterRows = useMemo(
    () =>
      meterDeltasSorted()
        .filter((m) => m.delta !== 0)
        .map((m) => ({
          ...m,
          fill: m.delta > 0.5 ? HEAT : m.delta > 0 ? FRICTION : COOL,
        })),
    [],
  );

  const momRows = useMemo(() => momDeltaSorted(), []);

  const mixRows = useMemo(() => propertyMixSorted(), []);

  const pieRows = useMemo(
    () =>
      PROPERTY_MIX.map((p) => ({
        ...p,
        fill:
          p.id === "office"
            ? OFFICE
            : p.id === "retail"
              ? RETAIL
              : p.id === "mixed"
                ? MIXED
                : OTHER,
      })),
    [],
  );

  const dyArea = useMemo(
    () => [
      {
        label: "Aug cohort",
        clear: DEBT_YIELD_BUCKETS.find((b) => b.id === "clear")!.balanceBn,
        friction: DEBT_YIELD_BUCKETS.find((b) => b.id === "friction")!.balanceBn,
        severe: DEBT_YIELD_BUCKETS.find((b) => b.id === "severe")!.balanceBn,
      },
    ],
    [],
  );

  const ledgerRows = useMemo(() => {
    return STRESS_MAP.filter((r) => ledgerBook === "all" || r.book === ledgerBook).map((r) => ({
      ...r,
      chargeOffPlot: r.chargeOff ?? (r.wallBn != null ? r.wallBn * 0.4 : 0.08),
      size: r.wallBn != null ? Math.max(120, r.wallBn * 80) : 90,
    }));
  }, [ledgerBook]);

  return (
    <div className="space-y-6" data-viz="bank-commercial-credit-update-202608">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-4 text-white shadow-sm">
        <p className="text-xs font-semibold uppercase tracking-wider text-rose-300">
          Aug 202608 vintage ?? Trepp hard maturities vs Q3 post
        </p>
        <p className="mt-1 text-lg font-bold sm:text-xl">
          Hard-maturity wall {fmtUsdBn(HEADLINE.hardMatNewBn)} (~
          {HEADLINE.hardMatMultiple.toFixed(1)}?? July) ?? NP {fmtMm(HEADLINE.npNewMm).replace("+", "")}{" "}
          all office ?? DY &lt;6% {fmtUsdBn(HEADLINE.dyBelow6Bn)}
        </p>
        <p className="mt-2 text-sm text-slate-300">
          Maturity wall doubled while Fed SA and July CMBS delinquency prints stay carried ??{" "}
          {HEADLINE.fedSaAsOf}
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={panel}
          onChange={setPanel}
          options={[
            { id: "meters", label: "?? meters" },
            { id: "mom", label: "July???Aug" },
            { id: "mix", label: "Property mix" },
            { id: "dyield", label: "Debt yield" },
            { id: "ledger", label: "Stress ledger" },
            { id: "fed", label: "Fed SA" },
          ]}
        />
        {panel === "mom" && (
          <ToggleGroup
            label="Compare"
            value={momLens}
            onChange={setMomLens}
            options={[
              { id: "levels", label: "Levels" },
              { id: "deltas", label: "Deltas" },
            ]}
          />
        )}
        {panel === "ledger" && (
          <ToggleGroup
            label="Book"
            value={ledgerBook}
            onChange={setLedgerBook}
            options={[
              { id: "all", label: "All" },
              { id: "bank", label: "Bank SA" },
              { id: "cmbs", label: "CMBS" },
              { id: "wall", label: "Maturity wall" },
            ]}
          />
        )}
      </div>

      {panel === "meters" && (
        <ChartCard
          title="What changed versus the Q3 update"
          subtitle="Signed maturity-wall deltas ??? July???Aug hard maturities, NP, special servicing, concentration"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={meterRows} layout="vertical" margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11 }} />
                <YAxis type="category" dataKey="label" width={178} tick={{ fontSize: 11 }} />
                <Tooltip
                  formatter={(value) => [Number(value).toFixed(2), "?? vs prior / July"]}
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as (typeof meterRows)[0] | undefined;
                    return row ? `${row.label}: ${row.deltaLabel}` : "";
                  }}
                />
                <ReferenceLine x={0} stroke="#64748b" />
                <Bar dataKey="delta" radius={[0, 4, 4, 0]}>
                  {meterRows.map((r) => (
                    <Cell key={r.id} fill={r.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <ul className="mt-3 grid gap-1 text-xs text-slate-600 sm:grid-cols-2">
            {VINTAGE_METERS.map((m) => (
              <li key={m.id}>
                <span className="font-semibold text-slate-800">{m.label}:</span> {m.deltaLabel}{" "}
                <span className="text-slate-500">??? {m.note}</span>
              </li>
            ))}
          </ul>
        </ChartCard>
      )}

      {panel === "mom" && (
        <ChartCard
          title="July ??? August hard-maturity series"
          subtitle="Wall 2.15?? ?? NP +$101.7M ?? special servicing ~2.2?? ?? top-5 share +4.28 pp"
        >
          {momLens === "levels" ? (
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={MOM_COMPARE} margin={{ left: 4, right: 12, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(value, name) => [
                      Number(value).toFixed(2),
                      name === "july" ? "July" : "August",
                    ]}
                  />
                  <Bar dataKey="july" fill={PRIOR} name="july" radius={[4, 4, 0, 0]} />
                  <Bar dataKey="august" fill={NEW} name="august" radius={[4, 4, 0, 0]} />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={momRows} layout="vertical" margin={{ left: 8, right: 16, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis type="category" dataKey="label" width={140} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(value) => [Number(value).toFixed(2), "?? July???Aug"]} />
                  <ReferenceLine x={0} stroke="#64748b" />
                  <Bar dataKey="delta" radius={[0, 4, 4, 0]}>
                    {momRows.map((r) => (
                      <Cell key={r.id} fill={HEAT} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </ChartCard>
      )}

      {panel === "mix" && (
        <ChartCard
          title="August property mix ??? office owns the NP stock"
          subtitle="Office $1.81B (32.86%) ?? retail $1.77B ?? mixed-use $1.38B (mostly one LA portfolio)"
        >
          <div className="grid gap-6 lg:grid-cols-2">
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieRows}
                    dataKey="balanceBn"
                    nameKey="short"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {pieRows.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(value, _n, item) => {
                      const row = item?.payload as (typeof pieRows)[0] | undefined;
                      return [
                        `${fmtUsdBn(Number(value))} (${row ? fmtPct(row.sharePct) : ""})`,
                        row?.label ?? "Balance",
                      ];
                    }}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={mixRows} layout="vertical" margin={{ left: 8, right: 12, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                  <XAxis type="number" tick={{ fontSize: 11 }} tickFormatter={(v) => `$${v}B`} />
                  <YAxis type="category" dataKey="short" width={72} tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(value) => [fmtUsdBn(Number(value)), "Balance"]}
                    labelFormatter={(_, payload) => {
                      const row = payload?.[0]?.payload as (typeof mixRows)[0] | undefined;
                      return row ? `${row.label}: ${row.note}` : "";
                    }}
                  />
                  <Bar dataKey="balanceBn" radius={[0, 4, 4, 0]}>
                    {mixRows.map((r) => (
                      <Cell
                        key={r.id}
                        fill={
                          r.id === "office"
                            ? OFFICE
                            : r.id === "retail"
                              ? RETAIL
                              : r.id === "mixed"
                                ? MIXED
                                : OTHER
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
          <ul className="mt-3 grid gap-1 text-xs text-slate-600 sm:grid-cols-2">
            {PROPERTY_MIX.map((p) => (
              <li key={p.id}>
                <span className="font-semibold text-slate-800">{p.label}:</span>{" "}
                {fmtUsdBn(p.balanceBn)} ?? {fmtPct(p.sharePct)} ??? {p.note}
              </li>
            ))}
          </ul>
        </ChartCard>
      )}

      {panel === "dyield" && (
        <ChartCard
          title="Debt yield is the binding refinance constraint"
          subtitle="$3.04B below 8% ?? $996M below 6% ?? ~$962M of the severe bucket still performing"
        >
          <div className="mb-4 h-[220px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={dyArea} margin={{ left: 4, right: 12, top: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} tickFormatter={(v) => `$${v}B`} />
                <Tooltip formatter={(value, name) => [fmtUsdBn(Number(value)), String(name)]} />
                <Area type="monotone" dataKey="clear" stackId="1" name="???8%" stroke={CLEAR} fill={CLEAR} />
                <Area
                  type="monotone"
                  dataKey="friction"
                  stackId="1"
                  name="6???8%"
                  stroke={FRICTION}
                  fill={FRICTION}
                />
                <Area
                  type="monotone"
                  dataKey="severe"
                  stackId="1"
                  name="<6%"
                  stroke={SEVERE}
                  fill={SEVERE}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
          <div className="h-[240px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={DEBT_YIELD_BUCKETS} margin={{ left: 4, right: 12, top: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} tickFormatter={(v) => `$${v}B`} />
                <Tooltip
                  formatter={(value) => [fmtUsdBn(Number(value)), "Balance"]}
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as (typeof DEBT_YIELD_BUCKETS)[0] | undefined;
                    return row ? `${row.label}: ${row.note}` : "";
                  }}
                />
                <Bar dataKey="balanceBn" radius={[4, 4, 0, 0]}>
                  {DEBT_YIELD_BUCKETS.map((b) => (
                    <Cell
                      key={b.id}
                      fill={b.severity === "clear" ? CLEAR : b.severity === "friction" ? FRICTION : SEVERE}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
            {YEAR_CALENDAR.map((y) => (
              <div key={y.id} className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2">
                <p className="text-xs font-semibold text-slate-500">{y.label}</p>
                <p className="text-sm font-bold text-slate-900">{fmtUsdBn(y.valueBn)}</p>
                <p className="text-xs text-slate-600">{y.note}</p>
              </div>
            ))}
          </div>
        </ChartCard>
      )}

      {panel === "ledger" && (
        <ChartCard
          title="Three ledgers ??? bank SA, CMBS delinquency, maturity wall"
          subtitle="Bank CRE still 1.56% delinq / 0.17% charge-off; CMBS office 11.91%; Aug office wall $1.81B"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ left: 8, right: 16, top: 12, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="delinquency"
                  name="Delinquency / stress proxy"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  domain={[0, 13]}
                />
                <YAxis
                  type="number"
                  dataKey="chargeOffPlot"
                  name="Charge-off / wall scaled"
                  tick={{ fontSize: 11 }}
                  domain={[-0.1, 4.2]}
                />
                <ZAxis type="number" dataKey="size" range={[70, 220]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value, name, item) => {
                    const row = item?.payload as (typeof ledgerRows)[0] | undefined;
                    if (name === "delinquency") return [fmtPct(Number(value)), "Delinq / proxy"];
                    if (row?.book === "wall") return [row.wallBn != null ? fmtUsdBn(row.wallBn) : "???", "Wall $B"];
                    if (row?.book !== "bank" && name === "chargeOffPlot") return ["n/a", "Charge-off"];
                    return [fmtPct(Number(value)), "Charge-off"];
                  }}
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as (typeof ledgerRows)[0] | undefined;
                    return row?.short ?? "";
                  }}
                />
                <Scatter data={ledgerRows} fill={CRE}>
                  {ledgerRows.map((r) => (
                    <Cell
                      key={r.short}
                      fill={
                        r.book === "wall"
                          ? OFFICE
                          : r.book === "cmbs"
                            ? HEAT
                            : r.short.includes("Cards")
                              ? CARDS
                              : CRE
                      }
                    />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "fed" && (
        <ChartCard
          title="Bank book still on 2026Q1 Fed SA ??? carried path"
          subtitle="No newer charge-off/delinquency SA vintage; maturity wall is the Aug signal, not a new Fed print"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={FED_SA_PATH} margin={{ left: 4, right: 12, top: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} tickFormatter={(v) => `${v}%`} />
                <Tooltip formatter={(value, name) => [fmtPct(Number(value)), String(name)]} />
                <Line
                  type="monotone"
                  dataKey="creDelinq"
                  name="CRE delinq"
                  stroke={CRE}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
                <Line
                  type="monotone"
                  dataKey="creChargeOff"
                  name="CRE charge-off"
                  stroke={CRE}
                  strokeWidth={2}
                  strokeDasharray="5 4"
                  dot={{ r: 2 }}
                />
                <Line
                  type="monotone"
                  dataKey="cardsChargeOff"
                  name="Cards charge-off"
                  stroke={CARDS}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
                <Line
                  type="monotone"
                  dataKey="ciChargeOff"
                  name="C&I charge-off"
                  stroke={CI}
                  strokeWidth={2}
                  dot={{ r: 2 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-3 text-xs text-slate-600">
            Carried levels: cards {fmtPct(HEADLINE.cardsChargeOff)} ?? CRE delinq {fmtPct(HEADLINE.creDelinq)} ??
            CRE charge-off {fmtPct(HEADLINE.creChargeOff)} ?? SLOOS NFNR still {HEADLINE.sloosNfnrNet} (July).
            Hard-maturity delta since Q3: wall {fmtBn(HEADLINE.hardMatDeltaBn)}.
          </p>
        </ChartCard>
      )}

      <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs text-slate-600">
        <p className="font-medium text-slate-700">Sources</p>
        <p className="mt-1">{SOURCE_NOTE}</p>
        <ul className="mt-2 flex flex-wrap gap-x-4 gap-y-1">
          {SOURCES.map((s) => (
            <li key={s.url}>
              <a href={s.url} className="text-sky-700 underline-offset-2 hover:underline">
                {s.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

