    "July???Aug",
    "Property mix",
    "Debt yield",
    "Stress ledger",
    "Fed SA",
  ]) {
    const btn = page.getByRole("button", { name: label });
    if (await btn.count()) {
      await btn.first().click();
      await page.waitForTimeout(400);
    }
  }

  await page.getByRole("button", { name: "July???Aug" }).first().click();
  await page
    .getByText("July ??? August hard-maturity series", { exact: false })
    .first()
    .waitFor({ timeout: 10000 });
  await page.getByRole("button", { name: "Deltas" }).first().click();
  await page.waitForTimeout(300);
  await page.getByRole("button", { name: "Levels" }).first().click();
  console.log("??? July???Aug compare toggles");

  await page.getByRole("button", { name: "Stress ledger" }).first().click();
  const bookWall = page.getByRole("button", { name: "Maturity wall" });
  if (await bookWall.count()) {
    await bookWall.first().click();
    await page.waitForTimeout(200);
    await page.getByRole("button", { name: "All" }).first().click();
  }
  console.log("??? Stress ledger book toggles");

  const audit = await auditVizInteractions(page, { slug });
  if (audit.issues?.length) {
    console.error("??? Viz interaction audit failed", audit);
    process.exit(1);
  }
  console.log("??? Viz interaction audit passed", audit.stats);
  if (audit.warnings?.length) {
    for (const w of audit.warnings) console.log("  ???", w);
  }

  const relevantConsole = consoleErrors.filter(
    (e) =>
      !e.includes("404") &&
      !e.includes("Failed to load resource") &&
      !e.includes("metamask") &&
      !e.includes("ObjectMultiplex") &&
      !/favicon|Download the React DevTools|hydration/i.test(e),
  );
  if (pageErrors.length) {
    console.error("??? Page errors", pageErrors.slice(0, 5));
    process.exit(1);
  }
  if (relevantConsole.length) {
    console.error("??? Console errors", relevantConsole.slice(0, 5));
    process.exit(1);
  }

  console.log(`??? QA passed: ${slug}`);
  await browser.close();
} finally {
  if (server) await stopStaticServer(server);
}

